"""ERPClaw Advanced Accounting -- Cross-domain reports and status

Aggregated reports and the skill status action.
Imported by db_query.py (unified router).
"""
import os
import sys

try:
    sys.path.insert(0, os.path.expanduser("~/.openclaw/erpclaw/lib"))
    from erpclaw_lib.response import ok, err, row_to_dict
except ImportError:
    pass

SKILL = "erpclaw-accounting-adv"
VERSION = "1.0.0"

ALL_TABLES = [
    "advacct_revenue_contract", "advacct_performance_obligation",
    "advacct_variable_consideration", "advacct_revenue_schedule",
    "advacct_lease", "advacct_lease_payment", "advacct_amortization_entry",
    "advacct_ic_transaction", "advacct_transfer_price_rule",
    "advacct_consolidation_group", "advacct_group_entity", "advacct_elimination_entry",
]


# ===========================================================================
# 1. standards-compliance-dashboard
# ===========================================================================
def standards_compliance_dashboard(conn, args):
    where, params = ["1=1"], []
    if getattr(args, "company_id", None):
        where.append("company_id = ?")
        params.append(args.company_id)
    where_sql = " AND ".join(where)

    # Revenue (ASC 606)
    revenue_contracts = conn.execute(
        f"SELECT COUNT(*) FROM advacct_revenue_contract WHERE {where_sql}", params
    ).fetchone()[0]
    unsatisfied_obligations = conn.execute(
        f"SELECT COUNT(*) FROM advacct_performance_obligation WHERE obligation_status != 'satisfied' AND {where_sql}", params
    ).fetchone()[0]

    # Leases (ASC 842)
    active_leases = conn.execute(
        f"SELECT COUNT(*) FROM advacct_lease WHERE lease_status = 'active' AND {where_sql}", params
    ).fetchone()[0]
    leases_without_rou = conn.execute(
        f"SELECT COUNT(*) FROM advacct_lease WHERE rou_asset_value IS NULL AND lease_status != 'draft' AND {where_sql}", params
    ).fetchone()[0]

    # Intercompany
    unposted_ic = conn.execute(
        f"SELECT COUNT(*) FROM advacct_ic_transaction WHERE ic_status NOT IN ('posted','eliminated') AND {where_sql}", params
    ).fetchone()[0]

    # Consolidation
    active_groups = conn.execute(
        f"SELECT COUNT(*) FROM advacct_consolidation_group WHERE group_status = 'active' AND {where_sql}", params
    ).fetchone()[0]

    ok({
        "report": "standards_compliance_dashboard",
        "asc_606": {
            "revenue_contracts": revenue_contracts,
            "unsatisfied_obligations": unsatisfied_obligations,
        },
        "asc_842": {
            "active_leases": active_leases,
            "leases_without_rou_calculation": leases_without_rou,
        },
        "intercompany": {
            "unposted_transactions": unposted_ic,
        },
        "consolidation": {
            "active_groups": active_groups,
        },
    })


# ===========================================================================
# 2. status
# ===========================================================================
def status_action(conn, args):
    counts = {}
    for tbl in ALL_TABLES:
        try:
            counts[tbl] = conn.execute(f"SELECT COUNT(*) FROM {tbl}").fetchone()[0]
        except Exception:
            counts[tbl] = 0

    ok({
        "skill": SKILL,
        "version": VERSION,
        "total_tables": len(ALL_TABLES),
        "record_counts": counts,
    })


# ---------------------------------------------------------------------------
# Action registry
# ---------------------------------------------------------------------------
ACTIONS = {
    "standards-compliance-dashboard": standards_compliance_dashboard,
    "status": status_action,
}

#!/usr/bin/env python3
"""ERPClaw OS — Dependency Resolver

Topological sort on module dependency graph from module_registry.json.
Resolves installation order, detects circular dependencies, and checks
for prefix collisions between modules.
"""
import json
import os
from collections import defaultdict


def load_registry(registry_path=None):
    """Load module registry JSON.

    Args:
        registry_path: Path to module_registry.json. If None, uses default location.

    Returns:
        dict of {module_name: module_info}
    """
    if registry_path is None:
        # Default: relative to erpclaw scripts directory
        registry_path = os.path.join(
            os.path.dirname(os.path.dirname(os.path.abspath(__file__))),
            "module_registry.json",
        )

    if not os.path.isfile(registry_path):
        return {}

    with open(registry_path, "r") as f:
        data = json.load(f)

    return data.get("modules", {})


def resolve_install_order(modules, registry=None, registry_path=None):
    """Resolve installation order via topological sort.

    Args:
        modules: list of module names to install
        registry: dict of {module_name: module_info} (optional, loaded from path if None)
        registry_path: path to module_registry.json

    Returns:
        dict with:
        - order: list of module names in install order
        - added_dependencies: modules added to satisfy dependencies
        - errors: list of error strings
    """
    if registry is None:
        registry = load_registry(registry_path)

    modules_set = set(modules)
    errors = []

    # 1. Expand dependencies: add all required modules
    all_needed = set()
    added_deps = set()

    def expand(mod_name):
        if mod_name in all_needed:
            return
        all_needed.add(mod_name)
        if mod_name not in registry:
            errors.append(f"Module '{mod_name}' not found in registry")
            return
        for dep in registry[mod_name].get("requires", []):
            if dep not in modules_set:
                added_deps.add(dep)
            expand(dep)

    for m in modules:
        expand(m)

    if errors:
        return {"order": [], "added_dependencies": list(added_deps), "errors": errors}

    # 2. Topological sort (Kahn's algorithm)
    # Build adjacency and in-degree
    in_degree = defaultdict(int)
    graph = defaultdict(list)

    for mod_name in all_needed:
        if mod_name not in in_degree:
            in_degree[mod_name] = 0
        for dep in registry.get(mod_name, {}).get("requires", []):
            if dep in all_needed:
                graph[dep].append(mod_name)
                in_degree[mod_name] += 1

    # Start with modules that have no dependencies
    queue = sorted([m for m in all_needed if in_degree[m] == 0])
    order = []

    while queue:
        node = queue.pop(0)
        order.append(node)
        for neighbor in sorted(graph[node]):
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if len(order) != len(all_needed):
        # Circular dependency detected
        remaining = all_needed - set(order)
        errors.append(f"Circular dependency detected among: {sorted(remaining)}")
        return {"order": order, "added_dependencies": list(added_deps), "errors": errors}

    return {
        "order": order,
        "added_dependencies": sorted(added_deps),
        "errors": [],
    }


def detect_circular_deps(modules, registry=None, registry_path=None):
    """Detect circular dependencies in a set of modules.

    Args:
        modules: list of module names
        registry: dict of {module_name: module_info}
        registry_path: path to module_registry.json

    Returns:
        list of cycles found (each cycle is a list of module names).
        Empty list = no cycles.
    """
    if registry is None:
        registry = load_registry(registry_path)

    # DFS-based cycle detection
    WHITE, GRAY, BLACK = 0, 1, 2
    color = {m: WHITE for m in modules if m in registry}
    cycles = []

    def dfs(node, path):
        color[node] = GRAY
        path.append(node)

        for dep in registry.get(node, {}).get("requires", []):
            if dep not in color:
                continue
            if color[dep] == GRAY:
                # Found cycle
                cycle_start = path.index(dep)
                cycles.append(path[cycle_start:] + [dep])
            elif color[dep] == WHITE:
                dfs(dep, path)

        path.pop()
        color[node] = BLACK

    for m in modules:
        if m in color and color[m] == WHITE:
            dfs(m, [])

    return cycles


def detect_prefix_collisions(modules, registry=None, registry_path=None):
    """Detect action prefix collisions between modules.

    Two modules with the same prefix would have overlapping action names.

    Args:
        modules: list of module names
        registry: dict of {module_name: module_info}
        registry_path: path to module_registry.json

    Returns:
        list of collision dicts: [{prefix, modules: [mod1, mod2]}]
    """
    if registry is None:
        registry = load_registry(registry_path)

    # Derive prefix from module name
    prefix_map = defaultdict(list)
    for mod_name in modules:
        if mod_name not in registry:
            continue
        # Common prefix derivation: module name or first part
        # e.g., healthclaw → health, educlaw → educ, retailclaw → retail
        prefix = mod_name.replace("claw", "").replace("-", "_").split("_")[0]
        if prefix:
            prefix_map[prefix].append(mod_name)

    collisions = []
    for prefix, mods in prefix_map.items():
        if len(mods) > 1:
            collisions.append({
                "prefix": prefix,
                "modules": mods,
            })

    return collisions

"""Post-test GL invariant verification.

Connects to a sandbox (or any) SQLite database and verifies that all
General Ledger entries satisfy the fundamental accounting invariants:

1. Global balance: SUM(debit) == SUM(credit) across all non-cancelled entries
2. Per-voucher balance: each voucher balances independently
3. No zero-zero entries: no gl_entry with debit=0 AND credit=0
4. Valid accounts: every account_id references an existing account
5. Valid fiscal year: every fiscal_year references an existing fiscal_year

All comparisons use Python Decimal — never float.
"""
import sqlite3
from decimal import Decimal, ROUND_HALF_UP


# Tolerance for balance comparisons (sub-cent)
_TOLERANCE = Decimal("0.001")


def check_gl_invariants(db_path: str) -> dict:
    """Run GL invariant checks against a database.

    Args:
        db_path: Absolute path to the SQLite database file.

    Returns:
        {
            "result": "pass" | "fail" | "skip",
            "reason": str (only if result == "skip"),
            "checks": [
                {"name": str, "result": "pass"|"fail", "detail": str},
                ...
            ],
            "violations": [str, ...]
        }
    """
    conn = sqlite3.connect(db_path)
    conn.row_factory = sqlite3.Row
    from erpclaw_lib.db import setup_pragmas
    setup_pragmas(conn)

    try:
        # Check if gl_entry table exists
        table_exists = conn.execute(
            "SELECT COUNT(*) FROM sqlite_master "
            "WHERE type='table' AND name='gl_entry'"
        ).fetchone()[0]
        if not table_exists:
            return {
                "result": "skip",
                "reason": "gl_entry table does not exist",
                "checks": [],
                "violations": [],
            }

        # Check if there are any GL entries
        entry_count = conn.execute(
            "SELECT COUNT(*) FROM gl_entry WHERE is_cancelled = 0"
        ).fetchone()[0]
        if entry_count == 0:
            return {
                "result": "skip",
                "reason": "no GL entries",
                "checks": [],
                "violations": [],
            }

        checks = []
        violations = []

        # --- Check 1: Global balance ---
        _check_global_balance(conn, checks, violations)

        # --- Check 2: Per-voucher balance ---
        _check_per_voucher_balance(conn, checks, violations)

        # --- Check 3: No zero-zero entries ---
        _check_no_zero_zero(conn, checks, violations)

        # --- Check 4: Valid accounts ---
        _check_valid_accounts(conn, checks, violations)

        # --- Check 5: Valid fiscal year ---
        _check_valid_fiscal_year(conn, checks, violations)

        overall = "pass" if all(c["result"] == "pass" for c in checks) else "fail"
        return {
            "result": overall,
            "checks": checks,
            "violations": violations,
        }
    finally:
        conn.close()


def _check_global_balance(conn, checks, violations):
    """Check 1: SUM(debit) == SUM(credit) globally for non-cancelled entries."""
    rows = conn.execute(
        "SELECT debit, credit FROM gl_entry WHERE is_cancelled = 0"
    ).fetchall()

    total_debit = Decimal("0")
    total_credit = Decimal("0")
    for row in rows:
        total_debit += Decimal(str(row["debit"]))
        total_credit += Decimal(str(row["credit"]))

    diff = abs(total_debit - total_credit)
    if diff <= _TOLERANCE:
        checks.append({
            "name": "global_balance",
            "result": "pass",
            "detail": f"Total debit={total_debit}, credit={total_credit}, diff={diff}",
        })
    else:
        detail = (
            f"IMBALANCE: total debit={total_debit}, "
            f"credit={total_credit}, diff={diff}"
        )
        checks.append({"name": "global_balance", "result": "fail", "detail": detail})
        violations.append(f"Global GL imbalance: {detail}")


def _check_per_voucher_balance(conn, checks, violations):
    """Check 2: Each voucher (type+id) must balance independently."""
    rows = conn.execute(
        "SELECT voucher_type, voucher_id, debit, credit "
        "FROM gl_entry WHERE is_cancelled = 0"
    ).fetchall()

    # Accumulate per voucher
    voucher_totals = {}
    for row in rows:
        key = (row["voucher_type"], row["voucher_id"])
        if key not in voucher_totals:
            voucher_totals[key] = {"debit": Decimal("0"), "credit": Decimal("0")}
        voucher_totals[key]["debit"] += Decimal(str(row["debit"]))
        voucher_totals[key]["credit"] += Decimal(str(row["credit"]))

    imbalanced = []
    for (vtype, vid), totals in voucher_totals.items():
        diff = abs(totals["debit"] - totals["credit"])
        if diff > _TOLERANCE:
            imbalanced.append({
                "voucher_type": vtype,
                "voucher_id": vid,
                "debit": str(totals["debit"]),
                "credit": str(totals["credit"]),
                "diff": str(diff),
            })

    if not imbalanced:
        checks.append({
            "name": "per_voucher_balance",
            "result": "pass",
            "detail": f"All {len(voucher_totals)} vouchers balanced",
        })
    else:
        detail = f"{len(imbalanced)} imbalanced voucher(s)"
        checks.append({
            "name": "per_voucher_balance",
            "result": "fail",
            "detail": detail,
        })
        for v in imbalanced:
            violations.append(
                f"Voucher {v['voucher_type']}:{v['voucher_id']} imbalanced: "
                f"debit={v['debit']}, credit={v['credit']}, diff={v['diff']}"
            )


def _check_no_zero_zero(conn, checks, violations):
    """Check 3: No gl_entry with both debit=0 AND credit=0 (non-cancelled)."""
    # Use Python Decimal to check — can't rely on CAST to REAL
    rows = conn.execute(
        "SELECT id, voucher_type, voucher_id, debit, credit "
        "FROM gl_entry WHERE is_cancelled = 0"
    ).fetchall()

    zero_zero = []
    for row in rows:
        d = Decimal(str(row["debit"]))
        c = Decimal(str(row["credit"]))
        if d == 0 and c == 0:
            zero_zero.append(dict(row))

    if not zero_zero:
        checks.append({
            "name": "no_zero_zero_entries",
            "result": "pass",
            "detail": "No zero-debit zero-credit entries found",
        })
    else:
        detail = f"{len(zero_zero)} zero-zero GL entry(ies) found"
        checks.append({
            "name": "no_zero_zero_entries",
            "result": "fail",
            "detail": detail,
        })
        for entry in zero_zero:
            violations.append(
                f"Zero-zero GL entry: id={entry['id']}, "
                f"voucher={entry['voucher_type']}:{entry['voucher_id']}"
            )


def _check_valid_accounts(conn, checks, violations):
    """Check 4: Every account_id in gl_entry references a valid account."""
    # Check if account table exists
    has_account = conn.execute(
        "SELECT COUNT(*) FROM sqlite_master "
        "WHERE type='table' AND name='account'"
    ).fetchone()[0]
    if not has_account:
        checks.append({
            "name": "valid_accounts",
            "result": "pass",
            "detail": "account table does not exist — skipped",
        })
        return

    orphans = conn.execute(
        "SELECT ge.id, ge.account_id, ge.voucher_type, ge.voucher_id "
        "FROM gl_entry ge "
        "LEFT JOIN account a ON ge.account_id = a.id "
        "WHERE a.id IS NULL AND ge.is_cancelled = 0"
    ).fetchall()

    if not orphans:
        checks.append({
            "name": "valid_accounts",
            "result": "pass",
            "detail": "All GL entries reference valid accounts",
        })
    else:
        detail = f"{len(orphans)} GL entry(ies) with invalid account_id"
        checks.append({"name": "valid_accounts", "result": "fail", "detail": detail})
        for o in orphans:
            violations.append(
                f"Invalid account_id: gl_entry.id={o['id']}, "
                f"account_id={o['account_id']}, "
                f"voucher={o['voucher_type']}:{o['voucher_id']}"
            )


def _check_valid_fiscal_year(conn, checks, violations):
    """Check 5: Every fiscal_year in gl_entry references a valid fiscal_year."""
    # Check if fiscal_year table exists
    has_fy = conn.execute(
        "SELECT COUNT(*) FROM sqlite_master "
        "WHERE type='table' AND name='fiscal_year'"
    ).fetchone()[0]
    if not has_fy:
        checks.append({
            "name": "valid_fiscal_year",
            "result": "pass",
            "detail": "fiscal_year table does not exist — skipped",
        })
        return

    # gl_entry.fiscal_year references fiscal_year.name
    orphans = conn.execute(
        "SELECT ge.id, ge.fiscal_year, ge.voucher_type, ge.voucher_id "
        "FROM gl_entry ge "
        "WHERE ge.fiscal_year IS NOT NULL "
        "AND ge.fiscal_year NOT IN (SELECT name FROM fiscal_year) "
        "AND ge.is_cancelled = 0"
    ).fetchall()

    if not orphans:
        checks.append({
            "name": "valid_fiscal_year",
            "result": "pass",
            "detail": "All GL entries reference valid fiscal years",
        })
    else:
        detail = f"{len(orphans)} GL entry(ies) with invalid fiscal_year"
        checks.append({
            "name": "valid_fiscal_year",
            "result": "fail",
            "detail": detail,
        })
        for o in orphans:
            violations.append(
                f"Invalid fiscal_year: gl_entry.id={o['id']}, "
                f"fiscal_year={o['fiscal_year']}, "
                f"voucher={o['voucher_type']}:{o['voucher_id']}"
            )

#!/usr/bin/env python3
"""ERPClaw OS — Suite Installation

Multi-module orchestrated installation with dependency resolution.
Takes a suite name or comma-separated module list, resolves dependencies,
and installs in correct order.
"""
import json
import os
import sys
import time

SCRIPT_DIR = os.path.dirname(os.path.abspath(__file__))
if SCRIPT_DIR not in sys.path:
    sys.path.insert(0, SCRIPT_DIR)

from dependency_resolver import (
    detect_circular_deps,
    detect_prefix_collisions,
    load_registry,
    resolve_install_order,
)

# ---------------------------------------------------------------------------
# Predefined Suites
# ---------------------------------------------------------------------------

SUITE_DEFINITIONS = {
    "healthcare-full": {
        "display_name": "Healthcare Full Stack",
        "description": "Complete healthcare suite: core health, dental, veterinary, mental health, home health",
        "modules": ["healthclaw", "healthclaw-dental", "healthclaw-vet",
                     "healthclaw-mental", "healthclaw-homehealth"],
    },
    "healthcare-dental": {
        "display_name": "Dental Practice",
        "description": "Dental practice: core health + dental",
        "modules": ["healthclaw", "healthclaw-dental"],
    },
    "healthcare-vet": {
        "display_name": "Veterinary Practice",
        "description": "Veterinary practice: core health + veterinary",
        "modules": ["healthclaw", "healthclaw-vet"],
    },
    "university": {
        "display_name": "University / Higher Education",
        "description": "Complete university suite: core education, higher ed, financial aid, scheduling, LMS, state reporting",
        "modules": ["educlaw", "educlaw-highered", "educlaw-finaid",
                     "educlaw-scheduling", "educlaw-lms", "educlaw-statereport"],
    },
    "k12": {
        "display_name": "K-12 School District",
        "description": "K-12 education: core education, K-12, scheduling, state reporting",
        "modules": ["educlaw", "educlaw-k12", "educlaw-scheduling",
                     "educlaw-statereport"],
    },
    "enterprise": {
        "display_name": "Enterprise ERP",
        "description": "Full enterprise: CRM, ops (manufacturing, projects, assets, quality, support), compliance, approvals, documents",
        "modules": ["erpclaw-growth", "erpclaw-ops", "erpclaw-compliance",
                     "erpclaw-approvals", "erpclaw-documents",
                     "erpclaw-alerts", "erpclaw-treasury"],
    },
    "retail": {
        "display_name": "Retail Business",
        "description": "Retail with POS and inventory management",
        "modules": ["retailclaw", "erpclaw-pos"],
    },
    "restaurant": {
        "display_name": "Restaurant / Food Service",
        "description": "Restaurant with POS, food management",
        "modules": ["foodclaw", "erpclaw-pos"],
    },
    "property-full": {
        "display_name": "Property Management Full",
        "description": "Residential and commercial property management",
        "modules": ["propertyclaw", "propertyclaw-commercial"],
    },
    "legal": {
        "display_name": "Legal Practice",
        "description": "Legal practice management with documents and e-sign",
        "modules": ["legalclaw", "erpclaw-documents", "erpclaw-esign"],
    },
    "nonprofit": {
        "display_name": "Nonprofit Organization",
        "description": "Nonprofit with compliance and CRM",
        "modules": ["nonprofitclaw", "erpclaw-compliance", "erpclaw-growth"],
    },
}


def list_suites():
    """List all available predefined suites.

    Returns:
        list of suite dicts with name, display_name, description, module_count
    """
    suites = []
    for name, info in sorted(SUITE_DEFINITIONS.items()):
        suites.append({
            "name": name,
            "display_name": info["display_name"],
            "description": info["description"],
            "module_count": len(info["modules"]),
            "modules": info["modules"],
        })
    return suites


def install_suite(suite_name=None, modules=None, registry_path=None, dry_run=False):
    """Orchestrate multi-module installation with dependency resolution.

    Args:
        suite_name: Name of a predefined suite (e.g., "healthcare-full")
        modules: Comma-separated string or list of module names
        registry_path: Path to module_registry.json
        dry_run: If True, only resolve and validate — don't install

    Returns:
        dict with install_order, validation, errors, etc.
    """
    start_time = time.time()

    # 1. Determine module list
    if suite_name:
        if suite_name not in SUITE_DEFINITIONS:
            available = sorted(SUITE_DEFINITIONS.keys())
            return {
                "result": "error",
                "error": f"Suite '{suite_name}' not found",
                "available_suites": available,
            }
        module_list = SUITE_DEFINITIONS[suite_name]["modules"]
    elif modules:
        if isinstance(modules, str):
            module_list = [m.strip() for m in modules.split(",") if m.strip()]
        else:
            module_list = modules
    else:
        return {
            "result": "error",
            "error": "Either --suite or --modules is required",
            "available_suites": sorted(SUITE_DEFINITIONS.keys()),
        }

    if not module_list:
        return {"result": "error", "error": "No modules specified"}

    # 2. Load registry
    registry = load_registry(registry_path)

    # 3. Check for circular dependencies
    cycles = detect_circular_deps(module_list, registry=registry)
    if cycles:
        return {
            "result": "error",
            "error": "Circular dependencies detected",
            "cycles": cycles,
        }

    # 4. Resolve installation order
    resolution = resolve_install_order(module_list, registry=registry)
    if resolution["errors"]:
        return {
            "result": "error",
            "error": "Dependency resolution failed",
            "errors": resolution["errors"],
        }

    # 5. Check for prefix collisions
    collisions = detect_prefix_collisions(resolution["order"], registry=registry)

    # 6. Build installation plan
    install_plan = []
    for mod_name in resolution["order"]:
        mod_info = registry.get(mod_name, {})
        install_plan.append({
            "module": mod_name,
            "display_name": mod_info.get("display_name", mod_name),
            "has_init_db": mod_info.get("has_init_db", False),
            "github": mod_info.get("github", ""),
            "is_dependency": mod_name in set(resolution["added_dependencies"]),
        })

    duration_ms = int((time.time() - start_time) * 1000)

    result = {
        "result": "planned" if dry_run else "ready",
        "suite": suite_name,
        "requested_modules": module_list,
        "install_order": resolution["order"],
        "install_plan": install_plan,
        "total_modules": len(resolution["order"]),
        "added_dependencies": resolution["added_dependencies"],
        "prefix_collisions": collisions,
        "duration_ms": duration_ms,
    }

    if dry_run:
        return result

    # In production, each module would be installed via module_manager.py.
    # For now, return the resolved plan for the caller to execute.
    return result


